insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('a584d16e-b3fe-458c-b441-09c6ad343fce', '4c23bf36-f633-482b-bc82-fd5ee0397496', 2, 'Dọc theo... (vị trí không gian song song với vật đã nêu)', 'N(địa điểm dài) ＋ にそって', 'Diễn tả vị trí không gian nằm dọc theo 1 vật có chiều dài (sông, đường, bờ đê...)', NULL, 68, 'pdf');
