insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('2bbbf84b-3620-4729-a744-3e7ffa8912b1', 'c43c2c60-b2d1-403e-bd79-47fed9c514d8', 2, 'Vì...nên kèm theo đó... (1 sự việc xảy ra tất yếu do sự việc trước gây ra)', 'N ＋ に伴って／に伴い', 'Diễn tả 1 hệ quả/hành động tất yếu xảy ra do 1 sự việc/quyết định trước đó', NULL, 68, 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('69191fba-6e24-4866-9aee-d2bce69f8081', NULL, 1, 'standard', '受験の際は、必ず受験票が必要になる。', 'Khi dự thi nhất định cần có phiếu dự thi.', '受験の＿＿＿、必ず受験票が必要になる。', '際は', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('69191fba-6e24-4866-9aee-d2bce69f8081', NULL, 2, 'daily', 'お帰りの際は、忘れ物にご注意ください。', 'Khi ra về, xin quý khách chú ý đồ đạc của mình.', 'お帰りの＿＿＿、忘れ物にご注意ください。', '際は', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('69191fba-6e24-4866-9aee-d2bce69f8081', NULL, 3, 'daily', '手続きをする際に、身分証明書が必要です。', 'Khi làm thủ tục, cần có giấy tờ tùy thân.', '手続きをする＿＿＿、身分証明書が必要です。', '際に', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f83c9267-cf1a-46d2-b3e6-2bd0fd450b82', NULL, 1, 'standard', '日本語能力試験の受験に際して、注意すべき点が三つあります。', 'Khi tham gia kì thi năng lực tiếng Nhật có 3 điểm cần chú ý.', '日本語能力試験の受験＿＿＿、注意すべき点が三つあります。', 'に際して', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f83c9267-cf1a-46d2-b3e6-2bd0fd450b82', NULL, 2, 'daily', '新規開店に際して、多くの方にご協力いただきました。', 'Nhân dịp khai trương, chúng tôi đã nhận được sự giúp đỡ của nhiều người.', '新規開店＿＿＿、多くの方にご協力いただきました。', 'に際して', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f83c9267-cf1a-46d2-b3e6-2bd0fd450b82', NULL, 3, 'daily', '契約を結ぶに際して、内容をよく確認してください。', 'Khi ký hợp đồng, xin hãy xác nhận kỹ nội dung.', '契約を結ぶ＿＿＿、内容をよく確認してください。', 'に際して', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bacf01b2-f9de-47b4-b9b1-955e245ecf8d', NULL, 1, 'standard', '日本で会談を行うにあたって、警備を強化する。', 'Tăng cường công tác phòng vệ khi tiến hành tổ chức hội đàm tại Nhật Bản.', '日本で会談を行う＿＿＿、警備を強化する。', 'にあたって', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bacf01b2-f9de-47b4-b9b1-955e245ecf8d', NULL, 2, 'daily', '新しい仕事を始めるにあたって、目標を立てた。', 'Khi bắt đầu công việc mới, tôi đã đặt ra mục tiêu.', '新しい仕事を始める＿＿＿、目標を立てた。', 'にあたって', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bacf01b2-f9de-47b4-b9b1-955e245ecf8d', NULL, 3, 'daily', '卒業するにあたって、先生に感謝の言葉を伝えた。', 'Nhân dịp tốt nghiệp, tôi đã gửi lời cảm ơn đến thầy cô.', '卒業する＿＿＿、先生に感謝の言葉を伝えた。', 'にあたって', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4c23bf36-f633-482b-bc82-fd5ee0397496', 'c32d21d0-fc6f-4c96-94a6-d0b22174ed20', 1, 'standard', 'お客様の要求にそって、新商品を開発する。', 'Phát triển sản phẩm mới dựa theo yêu cầu của khách hàng.', 'お客様の要求＿＿＿、新商品を開発する。', 'にそって', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4c23bf36-f633-482b-bc82-fd5ee0397496', 'c32d21d0-fc6f-4c96-94a6-d0b22174ed20', 2, 'daily', '計画にそって、作業を進めます。', 'Tiến hành công việc dựa theo kế hoạch.', '計画＿＿＿、作業を進めます。', 'にそって', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4c23bf36-f633-482b-bc82-fd5ee0397496', 'c32d21d0-fc6f-4c96-94a6-d0b22174ed20', 3, 'daily', 'マニュアルにそって、操作してください。', 'Hãy thao tác dựa theo hướng dẫn sử dụng.', 'マニュアル＿＿＿、操作してください。', 'にそって', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4c23bf36-f633-482b-bc82-fd5ee0397496', 'a584d16e-b3fe-458c-b441-09c6ad343fce', 1, 'standard', '花火大会の日は、大勢の人が土手にそって座っている。', 'Vào ngày lễ hội bắn pháo hoa có nhiều người ngồi dọc theo bờ đê.', '花火大会の日は、大勢の人が土手＿＿＿座っている。', 'にそって', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4c23bf36-f633-482b-bc82-fd5ee0397496', 'a584d16e-b3fe-458c-b441-09c6ad343fce', 2, 'daily', '川にそって、桜の木が植えられている。', 'Hàng cây hoa anh đào được trồng dọc theo dòng sông.', '川＿＿＿、桜の木が植えられている。', 'にそって', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4c23bf36-f633-482b-bc82-fd5ee0397496', 'a584d16e-b3fe-458c-b441-09c6ad343fce', 3, 'daily', '道にそって、店が並んでいる。', 'Các cửa hàng nối tiếp nhau dọc theo con đường.', '道＿＿＿、店が並んでいる。', 'にそって', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c43c2c60-b2d1-403e-bd79-47fed9c514d8', '9b108e5a-41a7-44e3-a06f-0eb047830423', 1, 'standard', 'インターネットの普及にともない、生活が豊かになる。', 'Cùng với sự phổ biến của internet mà cuộc sống trở nên phong phú hơn.', 'インターネットの普及＿＿＿、生活が豊かになる。', 'にともない', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c43c2c60-b2d1-403e-bd79-47fed9c514d8', '9b108e5a-41a7-44e3-a06f-0eb047830423', 2, 'daily', '技術の進歩にともなって、生活が便利になった。', 'Cùng với sự tiến bộ của công nghệ, cuộc sống đã trở nên tiện lợi hơn.', '技術の進歩＿＿＿、生活が便利になった。', 'にともなって', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c43c2c60-b2d1-403e-bd79-47fed9c514d8', '9b108e5a-41a7-44e3-a06f-0eb047830423', 3, 'daily', '少子化にともなって、学校の数が減っている。', 'Cùng với tình trạng ít con, số lượng trường học đang giảm đi.', '少子化＿＿＿、学校の数が減っている。', 'にともなって', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c43c2c60-b2d1-403e-bd79-47fed9c514d8', '2bbbf84b-3620-4729-a744-3e7ffa8912b1', 1, 'standard', '大学進学にともない、東京に引っ越した。', 'Vì tôi tiếp tục học lên Đại học nên đã chuyển đến Tokyo.', '大学進学＿＿＿、東京に引っ越した。', 'にともない', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c43c2c60-b2d1-403e-bd79-47fed9c514d8', '2bbbf84b-3620-4729-a744-3e7ffa8912b1', 2, 'daily', '結婚にともない、新しい家に住むことにした。', 'Vì kết hôn nên tôi đã quyết định chuyển đến sống ở nhà mới.', '結婚＿＿＿、新しい家に住むことにした。', 'にともない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c43c2c60-b2d1-403e-bd79-47fed9c514d8', '2bbbf84b-3620-4729-a744-3e7ffa8912b1', 3, 'daily', '転勤にともない、家族全員で引っ越すことになった。', 'Vì chuyển công tác nên cả gia đình phải chuyển nhà.', '転勤＿＿＿、家族全員で引っ越すことになった。', 'にともない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('95ccbce1-5544-444f-a2b0-0a2738ff2951', NULL, 1, 'standard', '料理の腕前にかけては自信がある。', 'Về kỹ năng nấu ăn thì tôi rất tự tin.', '料理の腕前＿＿＿自信がある。', 'にかけては', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('95ccbce1-5544-444f-a2b0-0a2738ff2951', NULL, 2, 'daily', '記憶力にかけては誰にも負けない。', 'Về trí nhớ thì tôi không thua kém ai.', '記憶力＿＿＿誰にも負けない。', 'にかけては', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('95ccbce1-5544-444f-a2b0-0a2738ff2951', NULL, 3, 'daily', 'スポーツにかけては彼が一番だ。', 'Về mặt thể thao thì anh ấy giỏi nhất.', 'スポーツ＿＿＿彼が一番だ。', 'にかけては', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('50f078d0-4037-4aef-95fc-87b4bc4cd755', NULL, 1, 'standard', '彼女、健康に気をつかっているにしてはよく風邪を引くね。', 'Cô ấy mặc dù lúc nào cũng chú ý đến sức khỏe thế mà lại bị cảm.', '彼女、健康に気をつかっている＿＿＿よく風邪を引くね。', 'にしては', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('50f078d0-4037-4aef-95fc-87b4bc4cd755', NULL, 2, 'daily', '彼は初心者にしては上手にピアノを弾く。', 'So với người mới học thì anh ấy chơi piano khá giỏi.', '彼は初心者＿＿＿上手にピアノを弾く。', 'にしては', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('50f078d0-4037-4aef-95fc-87b4bc4cd755', NULL, 3, 'daily', 'このレストランは値段が高いにしては、味がいまいちだ。', 'Nhà hàng này giá đắt vậy mà hương vị lại không được ngon.', 'このレストランは値段が高い＿＿＿、味がいまいちだ。', 'にしては', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('5b73d022-1662-43dc-bd41-a2a1ab1cda8a', NULL, 1, 'standard', '3時に家を出るにしても5時までに空港に到着するのは困難だ。', 'Cứ cho là ra khỏi nhà lúc 3 giờ chăng nữa thì việc đến sân bay trước 5 giờ vô cùng khó khăn.', '3時に家を出る＿＿＿5時までに空港に到着するのは困難だ。', 'にしても', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('5b73d022-1662-43dc-bd41-a2a1ab1cda8a', NULL, 2, 'daily', '忙しいにしても、返信ぐらいはできるはずだ。', 'Cho dù có bận thì ít nhất cũng có thể trả lời tin nhắn chứ.', '忙しい＿＿＿、返信ぐらいはできるはずだ。', 'にしても', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('5b73d022-1662-43dc-bd41-a2a1ab1cda8a', NULL, 3, 'daily', '冗談にしても、言っていいことと悪いことがある。', 'Dù là nói đùa thì cũng có điều nên nói và không nên nói.', '冗談＿＿＿、言っていいことと悪いことがある。', 'にしても', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('9a920628-8651-40e1-83bd-044e78ea4c5a', NULL, 1, 'standard', '彼は人目もかまわず、道で歌っている。', 'Anh ấy hát trên đường mà chẳng màng đến mọi người xung quanh.', '彼は人目＿＿＿、道で歌っている。', 'もかまわず', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('9a920628-8651-40e1-83bd-044e78ea4c5a', NULL, 2, 'daily', '彼女は服が濡れるのもかまわず、雨の中を走った。', 'Cô ấy chạy dưới mưa mặc kệ quần áo bị ướt.', '彼女は服が濡れる＿＿＿、雨の中を走った。', 'のもかまわず', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('9a920628-8651-40e1-83bd-044e78ea4c5a', NULL, 3, 'daily', '危険もかまわず、彼は火の中に飛び込んだ。', 'Anh ấy đã lao vào đám cháy mặc kệ nguy hiểm.', '危険＿＿＿、彼は火の中に飛び込んだ。', 'もかまわず', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('d9665e52-39ed-4990-98c2-06cd4362734f', NULL, 1, 'standard', '愛を込めて作ったチョコレートを彼に渡した。', 'Tôi đã tặng cho người yêu sô-cô-la với tất cả tình yêu của mình.', '愛＿＿＿作ったチョコレートを彼に渡した。', 'を込めて', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('d9665e52-39ed-4990-98c2-06cd4362734f', NULL, 2, 'daily', '感謝を込めて手紙を書いた。', 'Tôi đã viết thư với tất cả lòng biết ơn.', '感謝＿＿＿手紙を書いた。', 'を込めて', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('d9665e52-39ed-4990-98c2-06cd4362734f', NULL, 3, 'daily', '心を込めて料理を作ります。', 'Tôi nấu ăn với tất cả tấm lòng.', '心＿＿＿料理を作ります。', 'を込めて', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('6f582c9a-b656-4169-8c4c-057fe0293433', NULL, 1, 'standard', 'この仕事は社長をぬきにしては決められない。', 'Công việc này nếu không phải là Giám đốc thì không thể quyết định được.', 'この仕事は社長＿＿＿決められない。', 'をぬきにしては', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('6f582c9a-b656-4169-8c4c-057fe0293433', NULL, 2, 'daily', '彼の協力をぬきにしては、このプロジェクトは成功しなかっただろう。', 'Nếu không có sự hợp tác của anh ấy thì dự án này chắc đã không thành công.', '彼の協力＿＿＿、このプロジェクトは成功しなかっただろう。', 'をぬきにしては', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('6f582c9a-b656-4169-8c4c-057fe0293433', NULL, 3, 'daily', '冗談をぬきにして、真剣に話し合いましょう。', 'Bỏ qua chuyện đùa cợt, chúng ta hãy nói chuyện nghiêm túc.', '冗談＿＿＿、真剣に話し合いましょう。', 'をぬきにして', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, correct_answer, source_type) values ('69191fba-6e24-4866-9aee-d2bce69f8081', NULL, 'fill_blank', 'Điền vào chỗ trống: 受験の＿＿＿、必ず受験票が必要になる。', '際は', 'generated');
